import manifest from "@/config/toolImages.generated.json";

/**
 * Responsive image helper for the 18 tool illustrations.
 *
 * `tool.image` in config/site.ts stores the large WebP path
 * (e.g. /images/tools/podcasttools_01_title-generator-lg.webp).
 * This helper resolves the matching small/large variants + real pixel sizes
 * generated by `scripts/optimize-tool-images.mjs`.
 */
export interface ResponsiveImage {
  src: string;
  srcSet: string;
  width: number;
  height: number;
}

type Variant = { src: string; width: number; height: number };
const entries = manifest as Record<string, { sm: Variant; lg: Variant }>;

function keyFromPath(imagePath: string): string {
  const file = imagePath.split("/").pop() ?? "";
  return file.replace(/-(sm|lg)\.webp$/, "").replace(/\.(png|jpe?g|webp)$/, "");
}

export function getToolImage(imagePath: string): ResponsiveImage {
  const entry = entries[keyFromPath(imagePath)];
  if (!entry) {
    return { src: imagePath, srcSet: "", width: 960, height: 1200 };
  }
  return {
    src: entry.lg.src,
    srcSet: `${entry.sm.src} ${entry.sm.width}w, ${entry.lg.src} ${entry.lg.width}w`,
    width: entry.lg.width,
    height: entry.lg.height,
  };
}

/** Per-tool Open Graph card (1200x630), generated by scripts/generate-og-images.mjs */
export function getToolOgImage(slug: string): string {
  return `/og/tools/${slug}.png`;
}

/** Per-guide Open Graph card (1200x630) */
export function getGuideOgImage(slug: string): string {
  return `/og/guides/${slug}.png`;
}
